  'base-render.components-due-row-style.c007': "/* 错态：写在按钮旁边（不只染色）。 */",
  'base-render.components-due-row-style.c008': "/* 悬停：包在设备能力查询里（不是唯一通路——按钮本来就是按下去的）。 */",
