  /* ── packages/base-render/src/components/hour-band/style.ts（#1226 迁入） ── */
  'base-render.components-hour-band-style.c001': "/* hour-band（时段带 · 形态 A「单带＋整点刻度尺（0–23）＋下方明细行」）：一天摊成一条带，",
  'base-render.components-hour-band-style.c002': '   每段按"当天第几分钟"定位，**长度就是「多久」**；段宽时再写一遍时长，下面逐段列明细行。',
  'base-render.components-hour-band-style.c003': "   层次不靠阴影与大圆角（小票纸零阴影、大字报刊零圆角）：靠发丝线、字重与深浅阶梯 ⇒ 换皮只换取值。 */",
  'base-render.components-hour-band-style.c004': "/* 头部：标题 ＋ 用途 ＋ 合计（合计顶右缘；容器一窄，三件自己折行，谁也不压谁）。 */",
  'base-render.components-hour-band-style.c005': '/* 那条带：底的软色＝"这一天"，段＝"在做什么"（段是百分比定位，恒在带内）。 */',
  'base-render.components-hour-band-style.c006': "/* 段里的时长字：写在**卡面小牌**上（深浅块上的字不赌色阶亮度，换皮也读得清）。",
  'base-render.components-hour-band-style.c007': "   段太窄时本字不上屏（归一化期就判掉），时长另有明细行的读数兜底。 */",
  'base-render.components-hour-band-style.c008': "/* 整点刻度尺：**和带同一张 24 列模板**（刻度永远落在整点上）。 */",
