  'base-render.components-popover-menu-style.c002': "/* 层次：粗边 ＋ 外圈晕 ＋ 顶层（`popover` 的顶层是浏览器给的，不靠任何投影）。 */",
  /* ── packages/base-render/src/components/popover/noscript.ts（#1226 迁入） ── */
