  /* ── packages/base-render/src/components/rank-list/style.ts（#1227 迁入） ── */
  'base-render.components-rank-list-style.c001': "/* rank-list（榜单 · 形态 A「领奖台」）：前三名三张卡 ＋ 第 4 名起逐行；名次／名称／条／值／占比。",
  'base-render.components-rank-list-style.c002': "   层次不靠阴影与大圆角：靠发丝线、底色块、字重与顶边那道语义条 ⇒ 换皮只换取值。 */",
  'base-render.components-rank-list-style.c003': "/* 领奖台：三张等宽卡。`auto-fit` ＋ 固定下限 ⇒ 只有一两名时卡不会缩成三分之一宽。",
  'base-render.components-rank-list-style.c004': "   DOM 顺序仍是 1→2→3（读屏与键盘顺序不乱），宽档的「第 1 名居中」靠 `order` 摆。 */",
  'base-render.components-rank-list-style.c005': "/* 卡：`surface` 底 ＋ 一圈 `edge` 发丝线（零阴影的两套皮肤下靠这条线立起来）＋ 顶边一条语义色。 */",
  'base-render.components-rank-list-style.c006': "/* 第 1 名：顶边换成强调色 ＋ 更粗 ／ 读数大一号（`RANK_LIST_FIRST_VALUE_SCALE`）／名次走强调色的文本档。",
  'base-render.components-rank-list-style.c007': "   三样一起给，色不是唯一信息（换到墨黑强调的报刊皮肤，粗顶边与大字号照样读得出）。 */",
  'base-render.components-rank-list-style.c008': "/* 名称：本件的主角（条与值都从它派生）。长了换行，**不许 `…`**。 */",
  'base-render.components-rank-list-style.c009': "/* 读数：数字走 `font-num` ＋ 等宽数字；不写 `nowrap`（长读数宁可换行，也不许顶破容器）。 */",
  'base-render.components-rank-list-style.c010': "/* 占比：份额的精确读法（跨两段比份额看它，不看条长）。 */",
  'base-render.components-rank-list-style.c011': "/* 条：全榜共用一条刻度（长度＝这一名的值 ÷ 全榜最大值）。轨道走 `surface-2`，与皮肤无关地看得见。 */",
  'base-render.components-rank-list-style.c012': "/* 逐行：名次 ｜「名称 ＋ 条」那一格 ｜ 值 ｜ 占比。条在名称**下面**另起一行 ⇒ 名称永不与条抢宽度。 */",
  'base-render.components-rank-list-style.c013': "/* 口径行：这条榜单的数怎么算的、占比按什么合计（要读的正文，走 `ink-2` 不走更浅的一档）。 */",
  'base-render.components-rank-list-style.c014': "/* 本件自身不带可点元素。这一条是**地板**：调用方若把某一名包成链接，焦点必须看得见。 */",
  'base-render.components-rank-list-style.c015': "/* 窄容器（<{p0}px）：三张卡并排会把名称与读数挤成竖排 ⇒ 卡改竖排一列、",
  'base-render.components-rank-list-style.c016': "   名次回到自然顺序（1→2→3）；逐行区四列不动（条本来就在名称下面，名字那一格仍是弹性那一格）。 */",
  /* ── packages/base-render/src/components/rating-row/model.ts（#1227 迁入） ── */
