  /* ── packages/base-render/src/components/relation-picker/style-forms.ts（#1227 迁入） ── */
  'base-render.components-relation-picker-style-forms.c001': "/* relation-picker 形态段（`style-forms.ts`）：行内那一块、最近一排、「全部」组头、选完那一行。 */",
  'base-render.components-relation-picker-style-forms.c002': "/* 行内展开那一块：字段行下面推开的那一块（单列，窄档不并排）；选完收起时 `hidden`。 */",
  'base-render.components-relation-picker-style-forms.c003': "/* 最近一排：横排换行的那一排（窄档自动折成两行）；一枚一点就选中那一项。 */",
